#include <stdio.h>
// 先引入 <math.h>，让编译器认识平方根、乘方等数学运算函数或常量的声明。
#include <math.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 x。这里没有给初值，必须先成功赋值，再读取它。
    double x;
    // 按引号里的格式读取输入。& 后面的变量是存放结果的位置；本段基础例子假定输入符合说明。
    scanf("%lf", &x);
    // 声明 d。取得浮点绝对值，再把结果保存在变量中。
    double d = fabs(x - 2.0);
    // 检查 d  小于或等于  3.0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (d <= 3.0) {
        // 把格式串和后面的值按顺序对应后显示出来。其中 \n 表示输出换行。
        printf("NEAR\n");
    // 前面的 if 条件不满足时，改走这一支。同一组 if / else if / else 只选一条路径。
    } else {
        // 把格式串和后面的值按顺序对应后显示出来。其中 \n 表示输出换行。
        printf("FAR\n");
    }
    // 按顺序用 %.2f 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
    printf("%.2f\n", d);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

// 先引入 <stdio.h>，让编译器认识输入和输出函数或常量的声明。
#include <stdio.h>
// 先引入 <math.h>，让编译器认识平方根、乘方等数学运算函数或常量的声明。
#include <math.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明 x。这里没有给初值，必须先成功赋值，再读取它。
    double x;
    // 按引号里的格式读取输入。& 后面的变量是存放结果的位置；本段基础例子假定输入符合说明。
    scanf("%lf", &x);
    // 检查 x  小于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (x < 0) {
        // 显示括号中的字符串，最后自动补一个换行。
        puts("INVALID");
    // 前面的 if 条件不满足时，改走这一支。同一组 if / else if / else 只选一条路径。
    } else {
        // 声明 r。计算参数的实数平方根，再把函数结果保存下来；使用前确认输入非负。
        double r = sqrt(x);
        // 按顺序用 %.2f、%.2f 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
        printf("%.2f %.2f\n", r, pow(r, 2.0));
