    if (scanf("%d", &n) != 1)
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    // 声明 s，先计算右边的 0，再把结果作为它的初值。
    int s = 0;
    // 先做 int i = 1；每轮检查 i <= n；为真才执行循环体。执行完一轮后做 i++，再检查条件。
    for (int i = 1; i <= n; i++)
