void rotate(int *a, int *b, int *c) {
    // 声明 t，先计算右边的 *c，再把结果作为它的初值。
    int t = *c;
    // 先计算右边 *b，再把结果写入左边 *c；左边原有的值会被覆盖。
    *c = *b;
    // 先计算右边 *a，再把结果写入左边 *b；左边原有的值会被覆盖。
    *b = *a;
    // 先计算右边 t，再把结果写入左边 *a；左边原有的值会被覆盖。
    *a = t;
}
