// 定义 row_sum 函数。括号里写它接收的数据；调用时传入的值会交给这些参数。
int row_sum(const int a[][3], int row) {
    // 声明 sum，先计算右边的 0，再把结果作为它的初值。
    int sum = 0;
    // 先做 int c = 0；每轮检查 c < 3；为真才执行循环体。执行完一轮后做 c++，再检查条件。
    for (int c = 0; c < 3; c++) {
        // 把 sum 原有的值与 a[row][c] 按 + 运算，再把结果写回 sum。
        sum += a[row][c];
    }
    // 结束当前函数，把 sum 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
    return sum;
}
