// 先引入 <stdlib.h>，让编译器认识申请内存、字符串转数字等工具函数或常量的声明。
#include <stdlib.h>
// 先引入 <string.h>，让编译器认识字符串和内存块处理函数或常量的声明。
#include <string.h>

// 程序从 main 开始执行。void 表示此处不接收命令行参数。花括号内放要做的事情。
int main(void) {
    // 声明数组 word[11]，留出相应容量。这里没有初始化，读元素前要先成功赋值。
    char word[11];
    // 按引号里的格式读取输入。& 后面的变量是存放结果的位置；本段基础例子假定输入符合说明。
    scanf("%10s", word);
    // 声明 len。计算正确终止字符串的有效字节数，不包含结束符。
    size_t len = strlen(word);
    // 声明 *p。按所需字节数申请空间，保存返回的地址；失败为NULL，成功后内容还未初始化。
    char *p = malloc(len + 2);
    // 检查 p  等于  NULL。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (p == NULL) {
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    }
    // 复制或追加一个以 \0 结束的字符串，必须先确认目标容量连同结束符一起足够。
    strcpy(p, word);
    // 按字节移动数据，允许源和目标范围重叠，但两边都必须有足够有效空间。
    memmove(p + 1, p, len + 1);
    // 先计算右边 '#'，再把结果写入左边 p[0]；左边原有的值会被覆盖。
    p[0] = '#';
    // 显示括号中的字符串，最后自动补一个换行。
    puts(p);
    // 归还这块动态申请的内存。归还后不能再通过旧地址访问里面的数据。
    free(p);
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}

