    // 检查 f 是空指针，不能继续通过它访问数据。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (!f) {
        // 把操作名称和当前 errno 对应的错误说明输出到标准错误流，帮助定位失败原因。
        perror("data.txt");
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    }
    // 这是同一类型的一组声明，逗号分开各个变量：s[64] 此处未赋初值；previous[4] 初值为 ""。
    char s[64], previous[4] = "";
    // 这是同一类型的一组声明，逗号分开各个变量：line 初值为 0；first 初值为 0；ok 初值为 1。
    int line = 0, first = 0, ok = 1;
    // 先检查 fgets(s, sizeof s, f)。为真就进入循环体，为假就直接去循环后面。
    while (fgets(s, sizeof s, f)) {
        // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
        line++;
        // 声明 n。计算正确终止字符串的有效字节数，不包含结束符。
        size_t n = strlen(s);
        // 检查 n ，并且  s[n - 1]  等于  '\n'。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (n && s[n - 1] == '\n') {
            // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
            s[--n] = 0;
            // 检查 n ，并且  s[n - 1]  等于  '\r'。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
            if (n && s[n - 1] == '\r') {
                // 把对应变量增加或减少 1。若它在循环更新项里，这是走向下一轮或结束循环的一步。
                s[--n] = 0;
            }
        }
        // 检查 strcmp(s, "ON")  不等于  0 ，并且  strcmp(s, "OFF")  不等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
        if (strcmp(s, "ON") != 0 && strcmp(s, "OFF") != 0) {
            // 先计算右边 0，再把结果写入左边 ok；左边原有的值会被覆盖。
            ok = 0;
        // 前面的 if 条件不满足时，改走这一支。同一组 if / else if / else 只选一条路径。
        } else {
            // 检查 line  大于  1 ，并且  first  等于  0 ，并且  strcmp(s, previous)  等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
            if (line > 1 && first == 0 && strcmp(s, previous) == 0) {
                // 先计算右边 line，再把结果写入左边 first；左边原有的值会被覆盖。
                first = line;
            }
            // 复制或追加一个以 \0 结束的字符串，必须先确认目标容量连同结束符一起足够。
            strcpy(previous, s);
        }
    }
    // 检查 ferror(f)。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (ferror(f)) {
        // 先计算右边 0，再把结果写入左边 ok；左边原有的值会被覆盖。
        ok = 0;
    }
    // 检查 fclose(f)  不等于  0。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (fclose(f) != 0) {
        // 结束当前函数，把 1 作为结果交回调用处。返回后，本函数后面的语句不会继续执行。
        return 1;
    }
    // 检查 ok。条件成立才执行后面的语句；不成立就跳过这一步，继续往后。
    if (ok) {
        // 按顺序用 %d 显示对应参数，格式符要和参数类型匹配。其中 \n 表示输出换行。
        printf("%d\n", first);
    // 前面的 if 条件不满足时，改走这一支。同一组 if / else if / else 只选一条路径。
    } else {
        // 显示括号中的字符串，最后自动补一个换行。
        puts("INVALID");
    }
    // 结束当前函数，把 0 作为结果交回调用处。在 main 中，0 表示正常结束。
    return 0;
}
